using System;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Threading.Tasks;using UnityEngine;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using Sound2.LevelEditing;
public static class VerifySceneTargetClicks {
 static readonly BindingFlags Fields=BindingFlags.Instance|BindingFlags.NonPublic;
 static async Task Click(Mouse mouse){mouse.MakeCurrent();InputSystem.QueueStateEvent(mouse,new MouseState().WithButton(MouseButton.Left));await Task.Delay(100);InputSystem.QueueStateEvent(mouse,new MouseState());await Task.Delay(150);}
 public static async Task<object> Main(){var setup=UnityEngine.Object.FindAnyObjectByType<BaiYuTestScene>();var p=setup.player.GetComponent<PlayerController>();var interaction=p.GetComponent<PlayerInteraction>();var pickup=p.GetComponent<PlayerPickup>();
 var targets=setup.ActiveContent.GetComponentsInChildren<PickupItem>().Where(x=>x.name.StartsWith("可投掷球")).Take(3).Concat(new[]{setup.map.FindFloor(setup.player.CurrentFloor).GetComponentsInChildren<MapResource>().First().GetComponent<PickupItem>(),setup.ActiveContent.GetComponentsInChildren<PickupItem>().First(x=>x.name=="可搬运方块"),setup.ActiveContent.GetComponentInChildren<CoinPickup>().GetComponent<PickupItem>()}).ToArray();
 var originalSettings=InputSystem.settings;var savedSettings=UnityEngine.Object.Instantiate(originalSettings);var originalHideFlags=originalSettings.hideFlags;var testSettings=UnityEngine.Object.Instantiate(originalSettings);testSettings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;testSettings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;InputSystem.settings=testSettings;var oldMouse=Mouse.current;var oldKeyboard=Keyboard.current;var mouse=InputSystem.AddDevice<Mouse>();var keyboard=InputSystem.AddDevice<Keyboard>();var actions=new[]{"moveAction","lookAction"}.Select(n=>((InputActionReference)typeof(PlayerController).GetField(n,Fields).GetValue(p)).action).ToArray();var enabled=actions.Select(a=>a.enabled).ToArray();var rows=new List<object>();
 try {foreach(var a in actions)a.Disable();p.SetInputCaptured(true);
 foreach(var target in targets){if(pickup.HeldItem!=null)pickup.TryThrow();var floor=setup.map.FindFloor(setup.player.CurrentFloor);p.Teleport(new Vector3(target.transform.position.x,floor.transform.position.y+1.03f,target.transform.position.z-1));
 var d=target.InteractionPosition-p.ViewTransform.position;typeof(PlayerController).GetField("pitch",Fields).SetValue(p,-Mathf.Atan2(d.y,new Vector2(d.x,d.z).magnitude)*Mathf.Rad2Deg);typeof(PlayerController).GetField("yaw",Fields).SetValue(p,Mathf.Atan2(d.x,d.z)*Mathf.Rad2Deg);await Task.Delay(450);
 int calls=0;target.onInteract.AddListener(_=>calls++);var beforeFocus=interaction.FocusedTarget==target;float progress=interaction.RingProgress;
 await Click(mouse);rows.Add(new{target=target.name,type=target.GetType().Name,beforeFocus,progress,calls,held=pickup.HeldItem==target,active=target.gameObject.activeInHierarchy,subtitle=setup.player.GetComponent<PlayerSubtitles>().CurrentText,p.InputSuspended});
 if(pickup.HeldItem!=null){await Click(mouse);await Task.Delay(1100);}
 }
 }finally{InputSystem.RemoveDevice(mouse);InputSystem.RemoveDevice(keyboard);if(originalSettings!=null){InputSystem.settings=originalSettings;UnityEngine.Object.Destroy(savedSettings);}else{savedSettings.hideFlags=originalHideFlags;InputSystem.settings=savedSettings;}UnityEngine.Object.Destroy(testSettings);if(oldMouse!=null&&oldMouse.added)oldMouse.MakeCurrent();if(oldKeyboard!=null&&oldKeyboard.added)oldKeyboard.MakeCurrent();for(int i=0;i<actions.Length;i++)if(enabled[i])actions[i].Enable();}return rows;}
}
